using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void job_completed(Control o,string kind,long generation,Variant result)
    {
        if(result.VariantType!=Variant.Type.Dictionary)return;var data=result.AsGodotDictionary();string action=Get(data,"action","").AsString();long ownerId=unchecked((long)Session(o).GetInstanceId()),revision=Session(o).Get("revision").AsInt64();var playback=Field<Node>(o,"playback");var player=Field<AudioStreamPlayer>(o,"preview_player");var waveform=Field<Control>(o,"waveform");var status=Field<Label>(o,"status");string path=Get(data,"path","").AsString();
        switch(kind){case "media_scan":o.Call("_show_media_review",data);return;case "media_probe":o.Call("_confirm_media_repair",data);return;case "record_finalize":record_finalized(o,generation,data);return;case "relink_probe":o.Call("_review_audio_relink",data);return;case "timeline_midi":if(Session(o)!=Get(data,"owner_session").AsGodotObject()||revision!=Get(data,"revision",-1).AsInt64()){notice(o,"The composition changed while mapping MIDI. Repeat this action in the intended document.");return;}o.Call("_save_midi_export",Get(data,"midi",new Settings()),true);return;case "record_prepare":o.Call("_record_preparation_finished",generation,data);return;case "silence_audition":o.Call("_silence_audition_completed",generation,data);return;}
        if(kind is "analysis" or "loudness"&&!analysis_provenance_current(o,data,generation))return;if(kind=="wave_edit"&&Get(data,"owner_id",0).AsInt64()!=ownerId)return;if(kind=="render"&&action=="preview"&&(Get(data,"transport_token",-1).AsInt64()!=o.Get("_transport_token").AsInt64()||Get(data,"owner_id",0).AsInt64()!=ownerId||!o.Get("_transport_requested").AsBool())){remove_preview_file(path);return;}string error=Get(data,"error","").AsString();if(error.Length>0){status.Text=error;if(kind=="render"&&action=="preview"){cancel_exact_playback(o);playback.Call("stop",false);}if(kind is not "wave_detail" and not "preview")notice(o,error);return;}
        switch(kind)
        {
            case "breath_review":if(generation==revision)o.Call("_breath_review_ready",data);break;
            case "preset_audition":if(Get(data,"owner",0).AsInt64()!=ownerId){remove_preview_file(path);return;}player.Stop();var filePreview=Field<Node>(o,"asset_file_preview");filePreview.Call("close_file");error=filePreview.Call("open_file",path,"Master",new Settings(),true).AsString();if(error.Length>0){notice(o,error);remove_preview_file(path);}break;
            case "dialogue_batch":if(generation==revision)o.Call("_dialogue_batch_ready",data);break;
            case "preview":if(generation!=o.Get("_generation").AsInt64())return;var stream=Get(data,"stream").As<AudioStreamWav>();if(stream!=null){var cache=Dict(o,"_preview_cache");cache[data["cache_key"]]=stream;long bytes=0;foreach(var cached in cache.Values)bytes+=cached.As<AudioStreamWav>().Data.LongLength;while((cache.Count>12||bytes>48L*1024*1024)&&cache.Count>1){Variant oldest=default;foreach(var key in cache.Keys){oldest=key;break;}bytes-=cache[oldest].As<AudioStreamWav>().Data.LongLength;cache.Remove(oldest);}}set_preview(o,stream,Get(data,"payload",new Settings()).AsGodotDictionary());break;
            case "audition":var audition=Get(data,"stream").As<AudioStream>();if(audition!=null){player.Stream=audition;player.Play();}break;
            case "import":if(generation!=unchecked((long)Document(o).GetInstanceId()))return;if(Get(data,"seconds",0).AsDouble()<=0){notice(o,"Unsupported, empty or unknown-duration source: "+path);return;}var imported=Session(o).Call("insert_source",data["path"],data["at"].AsDouble(),data["track"].AsString(),path.GetFile()).AsGodotObject();if(imported!=null){Field<Control>(o,"library").Call("add_asset",path,path.GetFile(),data["seconds"].AsDouble());o.Call("fit_timeline");}break;
            case "drop_generator":if(generation!=revision)return;if(Get(data,"stream").AsGodotObject()!=null){var payload=data["payload"].AsGodotDictionary();payload["stream"]=data["stream"];insert_generator_payload(o,payload,data["at"].AsDouble(),data["track"].AsString());}break;
            case "notes":if(generation!=revision){render_dirty_notes(o);return;}bool modified=false;using(var edits=new AudioEditSessionOperations()){foreach(var raw in Get(data,"outputs",new GArray()).AsGodotArray()){var entry=raw.AsGodotDictionary();var actor=Document(o).Call("actor_for_clip",entry["clip_id"].AsString()).AsGodotObject();var clip=Document(o).Call("clip_for_id",entry["clip_id"].AsString()).AsGodotObject();if(actor==null||clip==null)continue;var rendered=Get(entry,"stream").As<AudioStreamWav>();if(rendered==null){status.Text="Instrument render needs valid samples and a source below 300 seconds, including note releases.";continue;}edits.apply_note_render(clip,actor,rendered,Get(entry,"signature","").AsString());modified=true;}}if(modified){Session(o).Set("revision",revision+1);Session(o).Set("dirty",true);Session(o).EmitSignal("changed");}break;
            case "composer":if(generation!=revision){notice(o,"The composition changed during music generation. Generate again to preserve those edits.");return;}o.Call("_apply_composer",data);break;
            case "wave_detail":var detailStream=waveform.Get("stream").AsGodotObject();if(detailStream==null||Get(data,"source_id",0).AsInt64()!=unchecked((long)detailStream.GetInstanceId()))return;waveform.Set("detail",data["samples"]);waveform.Set("detail_start",data["start"].AsDouble());waveform.QueueRedraw();break;
            case "spectrogram":var spectralStream=waveform.Get("stream").AsGodotObject();if(spectralStream==null||generation!=unchecked((long)spectralStream.GetInstanceId()))return;waveform.Set("spectrogram",ImageTexture.CreateFromImage(data["image"].As<Image>()));waveform.Set("spectrogram_start",data["start"].AsDouble());waveform.Set("spectrogram_duration",data["duration"].AsDouble());waveform.Set("show_spectrogram",true);waveform.QueueRedraw();break;
            case "wave_edit":if(generation!=revision){notice(o,"The clip changed during processing. Apply the selection edit again.");return;}Settings applied;using(var regions=new AudioRegionEditOperations())applied=regions.apply(Session(o),data);error=Get(applied,"error","").AsString();if(error.Length>0){notice(o,error);return;}string operation=data["operation"].AsString();if(operation is "copy" or "cut"){o.Set("_wave_clipboard",data["clipboard"]);o.Set("_wave_clipboard_rate",data["rate"].AsInt32());}if(operation=="copy"){status.Text="Copied sample selection.";return;}string focus=Get(applied,"focus_clip_id","").AsString();if(focus.Length>0)o.Call("edit_clip",focus);else{o.Set("_wave_clip_id","");waveform.Call("open",default(Variant));}status.Text="Edited selection; untouched source audio is preserved. Undo restores the original clip.";break;
            case "noise_profile":if(generation!=revision)return;var noiseActor=Document(o).Call("actor_for_clip",Get(data,"clip_id","").AsString()).AsGodotObject();if(noiseActor==null)return;SessionAction(o,"Learn spectral noise profile",()=>{using var effects=new AudioEffectsOperations();var effect=effects.create("noise_reduce");var parameters=effect["parameters"].AsGodotDictionary();parameters["noise_profile"]=data["noise_profile"];parameters["floor"]=data["floor"];var values=Dict(noiseActor,"values");var stack=Get(values,"effects",new GArray()).AsGodotArray();stack.Add(effect);values[new StringName("effects")]=stack;});status.Text="Learned a 15-band spectral profile from "+data["seconds"].AsDouble().ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" seconds. Render preview and adjust reduction/floor; noise overlapping speech cannot be perfectly removed.";break;
            case "loudness":accept_analysis_result(o,data,generation,true);break;case "analysis":accept_analysis_result(o,data,generation,false);break;
            case "alignment":if(generation!=revision||Get(data,"owner_id",0).AsInt64()!=ownerId)return;error=alignment_problem(o,Get(data,"ids",new GArray()).AsGodotArray());if(error.Length>0){notice(o,error);return;}if(Get(data,"confidence",0).AsDouble()<.25){notice(o,"No confident alignment was found. Adjust manually.");return;}SessionAction(o,"Align audio",()=>Session(o).Call("edit_clip",data["clip_id"].AsString(),new Settings{["start_time"]=Math.Max(0,data["base"].AsDouble()+data["offset"].AsDouble())}));status.Text="Aligned using normalized correlation ("+(data["confidence"].AsDouble()*100).ToString("F0",System.Globalization.CultureInfo.InvariantCulture)+"%).";break;
            case "match_levels":if(generation!=revision||Get(data,"owner_id",0).AsInt64()!=ownerId)return;foreach(var raw in data["clips"].AsGodotArray()){var entry=raw.AsGodotDictionary();error=smart_track_problem(o,Get(Document(o).Call("track_for_clip",entry["id"].AsString()).AsGodotDictionary(),"id","").AsString());if(error.Length>0){notice(o,error);return;}}SessionAction(o,"Match RMS levels",()=>{foreach(var raw in data["clips"].AsGodotArray()){var entry=raw.AsGodotDictionary();var actor=Document(o).Call("actor_for_clip",entry["id"].AsString()).AsGodotObject();if(actor!=null&&entry["db"].AsDouble()>-100)Dict(actor,"values")[new StringName("volume_db")]=Math.Clamp(Get(entry,"base_db",0).AsDouble()-20-entry["db"].AsDouble(),-30,18);}});break;
            case "ducking":if(generation!=revision||Get(data,"owner_id",0).AsInt64()!=ownerId)return;error=smart_track_problem(o,data["track"].AsString());if(error.Length>0){notice(o,error);return;}var target=Document(o).Call("track_for_id",data["track"].AsString()).AsGodotDictionary();if(target.Count>0)SessionAction(o,"Dialogue ducking",()=>{var curves=Get(target,"automation",new Settings()).AsGodotDictionary();curves["volume_db"]=data["points"];target["automation"]=curves;});break;
            case "render":render_finished(o,data,generation);break;
            case "export_stems":var failures=new System.Collections.Generic.List<string>();int count=0;foreach(var raw in data["results"].AsGodotArray()){var entry=raw.AsGodotDictionary();if(Get(entry,"success",false).AsBool())count++;else failures.Add(Get(entry,"error","Failed").AsString());}status.Text="Exported "+count+" stems.";if(failures.Count>0)notice(o,string.Join("\n",failures));break;
            case "save_preview":if(Get(data,"success",false).AsBool()){Field<Control>(o,"library").Call("add_asset",path,path.GetFile(),Get(data,"duration",0).AsDouble());status.Text="Saved generated audio.";}else notice(o,"Audio export failed. Check the encoder and destination.");break;
        }
    }
    public void render_finished(Control o,Settings data,long generation)
    {
        if(!Get(data,"success",false).AsBool()){notice(o,Get(data,"error","Audio render failed.").AsString());return;}string action=data["action"].AsString(),path=data["path"].AsString();var status=Field<Label>(o,"status");var playback=Field<Node>(o,"playback");if(action=="export"){status.Text="Exported "+path;return;}if(Get(data,"owner_id",0).AsInt64()!=unchecked((long)Session(o).GetInstanceId())){remove_preview_file(path);status.Text="Discarded a render for a different composition.";return;}if(generation!=Session(o).Get("revision").AsInt64()){remove_preview_file(path);status.Text="Discarded a stale preview; newer edits were preserved.";if(action=="preview"&&o.Get("_transport_requested").AsBool())o.CallDeferred("render_preview");return;}double at=data["at"].AsDouble();if(action=="preview"&&Get(data,"file_preview",false).AsBool()){if(!o.Get("_transport_requested").AsBool()||Get(data,"transport_token",-1).AsInt64()!=o.Get("_transport_token").AsInt64()){remove_preview_file(path);return;}var info=Get(data,"pcm_info",new Settings()).AsGodotDictionary();string error=Get(info,"error","Invalid PCM preview.").AsString();if(error.Length>0){remove_preview_file(path);cancel_exact_playback(o);notice(o,error);return;}o.Set("_transport_requested",false);error=playback.Call("play_file",path,at,info).AsString();if(error.Length>0){remove_preview_file(path);notice(o,error);}else{playback.Set("rendered_route_meters",Get(data,"route_meters",new Settings()));playback.Set("rendered_meter_start",Get(data,"meter_start",at).AsDouble());playback.Set("rendered_meter_hz",Get(data,"meter_hz",20).AsInt32());double monitor=Get(data,"monitor_from",at).AsDouble();if(monitor>at&&monitor<at+Get(info,"duration",0).AsDouble())playback.Call("seek",monitor);status.Text="Playing prepared PCM from disk; original sources remain unchanged.";}return;}var stream=Get(data,"stream").As<AudioStream>();if(stream==null){notice(o,"Render completed but could not be loaded.");return;}switch(action){case "preview":if(!o.Get("_transport_requested").AsBool()||Get(data,"transport_token",-1).AsInt64()!=o.Get("_transport_token").AsInt64())return;o.Set("_transport_requested",false);playback.Call("play_exact",stream,at);double monitor=Get(data,"monitor_from",at).AsDouble();if(monitor>at&&monitor<at+stream.GetLength())playback.Call("seek",monitor);remove_preview_file(path);break;case "scene":o.EmitSignal("use_in_scene",stream,Document(o).Get("title"));status.Text="Rendered audio is ready in Scene Workspace.";break;case "replace":string error=Session(o).Call("replace_rendered_clips",data["selection"],data["track_id"].AsString(),stream).AsString();if(error.Length>0){notice(o,error);return;}break;case "freeze_track":using(var freeze=new AudioGroupFreezeOperations()){string problem=freeze.apply(Session(o),data["track_id"].AsString(),stream);if(problem.Length>0)notice(o,problem);}break;case "bounce_track":SessionAction(o,"Bounce track",()=>{using var documents=new AudioDocumentOperations();var original=Document(o).Call("track_for_id",data["track_id"].AsString()).AsGodotDictionary();var track=documents.add_track(Document(o),"Bounced "+Get(original,"name","Track").AsString(),"audio");documents.insert_source(Document(o),stream,track["id"].AsString(),0,"Track bounce");original["mute"]=true;original["locked"]=true;});break;}if(action!="preview")Field<Control>(o,"library").Call("add_asset",path,path.GetFile(),stream.GetLength());
    }
}
